pushd $SRC/zlib
./configure --static --prefix="$WORK"
make -j$(nproc) all
make install
popd
pushd $SRC/zstd
make -j$(nproc) install PREFIX="$WORK"
popd
pushd "$SRC/jbigkit"
make clean
make -j$(nproc) lib
cp "$SRC"/jbigkit/libjbig/*.a "$WORK/lib/"
cp "$SRC"/jbigkit/libjbig/*.h "$WORK/include/"
popd
pushd $SRC/libjpeg-turbo
cmake . -DCMAKE_INSTALL_PREFIX="$WORK" -DENABLE_STATIC:bool=on
make -j$(nproc)
make install
popd
pushd $SRC/libpng
cat scripts/pnglibconf.dfa |   sed -e "s/option WARNING /option WARNING disabled/" > scripts/pnglibconf.dfa.temp
mv scripts/pnglibconf.dfa.temp scripts/pnglibconf.dfa
autoreconf -f -i
./configure   --prefix="$WORK"   --disable-shared   --enable-static   LDFLAGS="-L$WORK/lib"   CPPFLAGS="-I$WORK/include"
make -j$(nproc)
make install
popd
pushd $SRC/libwebp
export WEBP_CFLAGS="$CFLAGS -DWEBP_MAX_IMAGE_SIZE=838860800" # 800MiB
./autogen.sh
./configure   --enable-libwebpdemux   --enable-libwebpmux   --disable-shared   --disable-jpeg   --disable-tiff   --disable-gif   --disable-wic   --disable-threading   --prefix="$WORK"   CFLAGS="$WEBP_CFLAGS"
make clean
make -j$(nproc)
make install
popd
pushd "$SRC/libtiff"
cmake . -DCMAKE_INSTALL_PREFIX="$WORK" -DBUILD_SHARED_LIBS=off
make clean
make -j$(nproc)
make install
popd
export LEPTONICA_LIBS="$WORK/lib/libjbig.a $WORK/lib/libzstd.a $WORK/lib/libwebp.a $WORK/lib/libpng.a"
./autogen.sh
./configure   --enable-static   --disable-shared   --with-libpng   --with-zlib   --with-jpeg   --with-libwebp   --with-libtiff   --prefix="$WORK"   LIBS="$LEPTONICA_LIBS"   LDFLAGS="-L$WORK/lib"   CPPFLAGS="-I$WORK/include"
make -j$(nproc)
make install
